provenance.program:
functions {
  vector adstock(vector x, real r) {
    int n = rows(x);
    vector[n] w;
    w[1] = 1;
    for (l in 2:n) {
      w[l] = w[l - 1] * r;
    }
    vector[n] a;
    a[1] = x[1];
    for (t in 2:n) {
      a[t] = x[t] + r * a[t - 1];
    }
    return a / sum(w);
  }
  vector hill(vector a, real k, real n) {
    vector[rows(a)] h;
    for (t in 1:rows(a)) {
      h[t] = a[t] > 0 ? inv_logit(n * (log(a[t]) - log(k))) : 0;
    }
    return h;
  }
  vector saturate(vector a, real k, vector slope, int m) {
    if (rows(slope) == 0) {
      return tanh(atanh(0.5) * a / k);
    }
    return hill(a, k, slope[m]);
  }
  matrix saturated(matrix spend, array[] int window, vector retention, vector half,
                   vector slope) {
    matrix[size(window), cols(spend)] h;
    for (m in 1:cols(spend)) {
      vector[rows(spend)] a = adstock(spend[:, m], retention[m]);
      h[:, m] = saturate(a[window], half[m], slope, m);
    }
    return h;
  }
  matrix effects(array[] matrix h, vector weight, vector window_spend, vector log_roi,
                 vector scale, matrix z) {
    int G = size(h);
    int M = cols(h[1]);
    int N = rows(h[1]);
    matrix[G, M] factor;
    vector[M] reach = rep_vector(0, M);
    for (g in 1:G) {
      factor[g] = exp(scale' .* z[g]);
      reach += weight[g] * (factor[g] .* (rep_row_vector(1, N) * h[g]))';
    }
    vector[M] b = exp(log_roi) .* window_spend ./ reach;
    matrix[G, M] beta;
    for (g in 1:G) {
      beta[g] = b' .* factor[g];
    }
    return beta;
  }
  vector means(array[] matrix h, matrix beta, array[] int geo, array[] int period,
               matrix calendar, array[] matrix controls, vector base, vector calendar_coef,
               vector control_coef) {
    vector[rows(calendar)] moved = 1 + calendar * calendar_coef;
    vector[size(geo)] mu;
    for (o in 1:size(geo)) {
      int g = geo[o];
      int t = period[o];
      mu[o] = base[g] * moved[t] + controls[g][t] * control_coef + h[g][t] * beta[g]';
    }
    return mu;
  }
  vector estimated(matrix as_run, matrix as_planned, array[] int estimate_channel,
                   array[] int estimate_readout, matrix tested, matrix beta, vector retention,
                   vector half, vector slope) {
    int L = cols(as_run);
    vector[size(estimate_readout)] mean;
    for (e in 1:size(estimate_readout)) {
      int m = estimate_channel[e];
      vector[L] hr = saturate(adstock(as_run[e]', retention[m]), half[m], slope, m);
      vector[L] hp = saturate(adstock(as_planned[e]', retention[m]), half[m], slope, m);
      mean[e] = tested[e] * beta[:, m]
                * sum(hr[estimate_readout[e]:L] - hp[estimate_readout[e]:L]);
    }
    return mean;
  }
}
data {
  int<lower=2> G;
  int<lower=1> L;
  int<lower=1> N;
  array[N] int<lower=1, upper=L> window;
  int<lower=1> O;
  array[O] int<lower=1, upper=G> geo;
  array[O] int<lower=1, upper=N> period;
  vector[O] y;
  vector<lower=0>[G] weight;
  int<lower=1> M;
  array[G] matrix[L, M] spend;
  vector<lower=0>[M] window_spend;
  vector[M] roi_mu;
  vector<lower=0>[M] roi_sigma;
  real<lower=0> spread_scale;
  int<lower=0> P;
  matrix[N, P] calendar;
  int<lower=0> C;
  array[G] matrix[N, C] controls;
  vector[C] control_lower;
  vector[C] control_upper;
  int<lower=0, upper=1> student;
  int<lower=0, upper=1> tanh_curve;
  array[M] int<lower=0, upper=1> centred;
  int<lower=0> E;
  array[E] int<lower=1, upper=M> estimate_channel;
  matrix[E, L] as_run;
  matrix[E, L] as_planned;
  array[E] int<lower=1, upper=L> estimate_readout;
  matrix<lower=0>[E, G] tested;
  vector[E] lift;
  vector<lower=0>[E] lift_se;
}
transformed data {
  matrix[G, G - 1] helmert = rep_matrix(0, G, G - 1);
  for (k in 1:(G - 1)) {
    for (g in 1:k) {
      helmert[g, k] = 1 / sqrt(k * (k + 1.0));
    }
    helmert[k + 1, k] = -k / sqrt(k * (k + 1.0));
  }
}
parameters {
  vector[M] log_roi;
  vector<lower=0, upper=1>[M] retention;
  vector<lower=0>[M] half;
  vector<lower=0>[tanh_curve ? 0 : M] slope;
  vector<lower=0>[M] spread;
  array[M] vector[G - 1] deviation;
  vector<lower=0>[G] base;
  vector[P] calendar_coef;
  vector<lower=control_lower, upper=control_upper>[C] control_coef;
  real<lower=0> sigma;
  array[student] real<lower=0> nu;
}
model {
  matrix[G, M] z;
  vector[M] effect_scale;
  for (m in 1:M) {
    z[:, m] = helmert * deviation[m];
    effect_scale[m] = centred[m] ? 1 : spread[m];
  }
  array[G] matrix[N, M] h;
  for (g in 1:G) {
    h[g] = saturated(spend[g], window, retention, half, slope);
  }
  matrix[G, M] beta = effects(h, weight, window_spend, log_roi, effect_scale, z);
  vector[O] mu = means(h, beta, geo, period, calendar, controls, base, calendar_coef,
                       control_coef);
  vector[O] scale = sigma ./ sqrt(weight[geo]);
  log_roi ~ normal(roi_mu, roi_sigma);
  retention ~ beta(1, 3);
  half ~ lognormal(0, 1);
  slope ~ lognormal(0, 0.5);
  spread ~ normal(0, spread_scale);
  for (m in 1:M) {
    deviation[m] ~ normal(0, centred[m] ? spread[m] : 1);
  }
  base ~ lognormal(0, 1);
  calendar_coef ~ std_normal();
  control_coef ~ std_normal();
  sigma ~ std_normal();
  if (student) {
    nu[1] ~ gamma(2, 0.1);
    y ~ student_t(nu[1], mu, scale);
  } else {
    y ~ normal(mu, scale);
  }
  lift ~ normal(estimated(as_run, as_planned, estimate_channel, estimate_readout, tested, beta,
                          retention, half, slope),
                lift_se);
}
generated quantities {
  vector[O + E] log_lik;
  {
    matrix[G, M] z;
    vector[M] effect_scale;
    for (m in 1:M) {
      z[:, m] = helmert * deviation[m];
      effect_scale[m] = centred[m] ? 1 : spread[m];
    }
    array[G] matrix[N, M] h;
    for (g in 1:G) {
      h[g] = saturated(spend[g], window, retention, half, slope);
    }
    matrix[G, M] beta = effects(h, weight, window_spend, log_roi, effect_scale, z);
    vector[O] mu = means(h, beta, geo, period, calendar, controls, base, calendar_coef,
                         control_coef);
    vector[O] scale = sigma ./ sqrt(weight[geo]);
    for (o in 1:O) {
      if (student) {
        log_lik[o] = student_t_lpdf(y[o] | nu[1], mu[o], scale[o]);
      } else {
        log_lik[o] = normal_lpdf(y[o] | mu[o], scale[o]);
      }
    }
    vector[E] l = estimated(as_run, as_planned, estimate_channel, estimate_readout, tested, beta,
                            retention, half, slope);
    for (e in 1:E) {
      log_lik[O + e] = normal_lpdf(lift[e] | l[e], lift_se[e]);
    }
  }
}
